mapper.select:
SELECT cr.seq AS roomId, NVL(cr.name, tp.title) AS roomName, cr.category, CASE WHEN cr.category = 0 THEN '동행' WHEN cr.category = 1 THEN '매칭' END AS displayCategory, admin.nickname AS partnerNickname, last_log.detail AS lastMessage, last_log.regdate AS regdate, CASE WHEN last_log.regdate IS NULL THEN '' ELSE TO_CHAR(last_log.regdate, 'MM-DD HH24:MI') END AS roomTime, 0 AS active FROM chattingroom cr INNER JOIN user_chat uc ON cr.seq = uc.seqChattingroom LEFT JOIN travel_post tp ON cr.seqTravelPost = tp.seqTravelPost LEFT JOIN ( SELECT seqChattingroom, detail, regdate FROM ( SELECT cl.seqChattingroom, cl.detail, cl.regdate, cl.seq, ROW_NUMBER() OVER ( PARTITION BY cl.seqChattingroom ORDER BY cl.regdate DESC, cl.seq DESC ) AS rn FROM chat_log cl ) WHERE rn = 1 ) last_log ON cr.seq = last_log.seqChattingroom LEFT JOIN ( SELECT uc1.seqChattingroom, m.nickname FROM user_chat uc1 INNER JOIN member m ON uc1.seqMember = m.seqMember WHERE uc1.auth = 0 ) admin ON cr.seq = admin.seqChattingroom WHERE uc.seqMember = #{seqMember} AND uc.isActive = 1
AND cr.category = #{category}
ORDER BY last_log.regdate DESC NULLS LAST, cr.seq DESC

SELECT nickname
FROM member
WHERE seqMember = #{seqMember}

mapper.update:
UPDATE user_chat
SET isActive = 0
WHERE seqChattingroom = #{roomId}
  AND seqMember = #{userId}
